Plan: Transfer exclusive ownership of each batch buffer at the ready/free handoff.

```c
#include <pthread.h>
#include <semaphore.h>
#include <assert.h>
static sem_t free_slot[2],ready[2];
static int batch[2][3],sum;
static void *format(void *p) {
    (void)p;
    for(int b=0;b<4;b++) {
        int slot=b%2; assert(sem_wait(&(free_slot[slot])) == 0);
        for(int j=0;j<3;j++) batch[slot][j]=3*b+j+1;
        assert(sem_post(&(ready[slot])) == 0);
    } return NULL;
}
static void *write_batch(void *p) {
    (void)p;
    for(int b=0;b<4;b++) {
        int slot=b%2; assert(sem_wait(&(ready[slot])) == 0);
        for(int j=0;j<3;j++) { assert(batch[slot][j]==3*b+j+1); sum+=batch[slot][j]; }
        assert(sem_post(&(free_slot[slot])) == 0);
    } return NULL;
}
int main(void) {
    pthread_t f,w;
    for(int i=0;i<2;i++) { assert((sem_init(&free_slot[i],0,1)) != -1); assert((sem_init(&ready[i],0,0)) != -1); }
    assert((pthread_create(&w,NULL,write_batch,NULL)) == 0); assert((pthread_create(&f,NULL,format,NULL)) == 0);
    assert((pthread_join(f,NULL)) == 0); assert((pthread_join(w,NULL)) == 0); assert(sum==78);
    for(int i=0;i<2;i++) { assert((sem_destroy(&free_slot[i])) != -1); assert((sem_destroy(&ready[i])) != -1); }
    return 0;
}
```

Why it is correct: The formatter waits for free before overwriting; the writer waits for ready before reading and returns free only after the whole batch. Each slot has one owner at a time, and semaphore publication orders its contents. Fixed batch counts avoid shutdown ambiguity.

