Plan: Initialize a private node and retry a release CAS to link it at head.

```c
#include <pthread.h>
#include <stdlib.h>
#include <assert.h>
typedef struct Node { int id; struct Node *next; } Node;
static Node *head;
static int ids[4];
static void *push(void *p) {
    Node *n=malloc(sizeof *n); assert(n); n->id=*(int *)p;
    Node *old=__atomic_load_n(&head,__ATOMIC_ACQUIRE);
    do { n->next=old; } while(!__atomic_compare_exchange_n(&head,&old,n,0,__ATOMIC_RELEASE,__ATOMIC_RELAXED));
    return NULL;
}
int main(void) {
    pthread_t t[4];
    for(int i=0;i<4;i++) { ids[i]=i; assert((pthread_create(&t[i],NULL,push,&ids[i])) == 0); }
    for(int i=0;i<4;i++) assert((pthread_join(t[i],NULL)) == 0);
    Node *n=__atomic_load_n(&head,__ATOMIC_ACQUIRE); int seen[4]={0},count=0;
    while(n) { Node *next=n->next; assert(n->id>=0 && n->id<4); ++seen[n->id]; ++count; free(n); n=next; }
    for(int i=0;i<4;i++) assert(seen[i]==1);
    assert(count==4); return 0;
}
```

Why it is correct: A CAS failure refreshes old and the next attempt rewrites n->next. Nodes are never removed or reused during pushes, so head cannot undergo an ABA cycle. Only main traverses and frees after joins. Finite pushes terminate under scheduling progress; lock-free pointer support is platform-dependent.

