Plan: Use species quotas for entry and a generation predicate for group completion.

```c
#include <pthread.h>
#include <semaphore.h>
#include <assert.h>
static sem_t h,o;
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static int generation,hs,os,molecules,kind[9]={0,1,0,0,0,1,0,1,0};
static void *atom(void *p) {
    int oxygen=*(int *)p; if(oxygen) assert(sem_wait(&(o)) == 0); else assert(sem_wait(&(h)) == 0);
    assert((pthread_mutex_lock(&m)) == 0); int mine=generation;
    if(oxygen) ++os; else ++hs;
    if(hs+os==3) {
        assert(hs==2 && os==1); hs=os=0; ++molecules; ++generation;
        assert(sem_post(&(h)) == 0); assert(sem_post(&(h)) == 0); assert(sem_post(&(o)) == 0); assert((pthread_cond_broadcast(&cv)) == 0);
    } else while(generation==mine) assert((pthread_cond_wait(&cv,&m)) == 0);
    assert((pthread_mutex_unlock(&m)) == 0); return NULL;
}
int main(void) {
    pthread_t t[9]; assert((sem_init(&h,0,2)) != -1); assert((sem_init(&o,0,1)) != -1);
    for(int i=0;i<9;i++) assert((pthread_create(&t[i],NULL,atom,&kind[i])) == 0);
    for(int i=0;i<9;i++) assert((pthread_join(t[i],NULL)) == 0);
    assert(molecules==3 && hs==0 && os==0);
    assert((sem_destroy(&h)) != -1); assert((sem_destroy(&o)) != -1); assert((pthread_cond_destroy(&cv)) == 0); assert((pthread_mutex_destroy(&m)) == 0); return 0;
}
```

Why it is correct: At most two H and one O enter an unfinished generation. The third arrival validates composition and advances the generation before replenishing permits. Waiters compare their saved generation, so later molecules cannot trap earlier atoms. No atom waits while holding a resource needed for the third arrival beyond the mutex released by cond_wait.

