Plan: Return a leader flag only to the last arrival and synchronize again after its reduction.

```c
#include <pthread.h>
#include <assert.h>
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static int arrived,generation,ids[3],part[3],total;
static int barrier(void) {
    assert((pthread_mutex_lock(&m)) == 0); int mine=generation,leader=0;
    if(++arrived==3) { leader=1; arrived=0; ++generation; assert((pthread_cond_broadcast(&cv)) == 0); }
    else while(generation==mine) assert((pthread_cond_wait(&cv,&m)) == 0);
    assert((pthread_mutex_unlock(&m)) == 0); return leader;
}
static void *worker(void *p) {
    int id=*(int *)p; part[id]=id+1;
    if(barrier()) { total=part[0]+part[1]+part[2]; }
    (void)barrier(); assert(total==6); return NULL;
}
int main(void) {
    pthread_t t[3];
    for(int i=0;i<3;i++) { ids[i]=i; assert((pthread_create(&t[i],NULL,worker,&ids[i])) == 0); }
    for(int i=0;i<3;i++) assert((pthread_join(t[i],NULL)) == 0);
    assert(total==6 && generation==2); assert((pthread_cond_destroy(&cv)) == 0); assert((pthread_mutex_destroy(&m)) == 0); return 0;
}
```

Why it is correct: The first barrier orders disjoint partial writes before the unique coordinator reads them. Exactly one thread writes total. The second generation barrier orders that write before all assertions, avoiding a post-barrier coordinator race.

