Plan: Protect queue state with m, wait on predicates in while loops, and broadcast durable closure.

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
enum { CAP=2, ITEMS=13 };
static int buf[CAP],head,tail,count,closed,sum;
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t ne=PTHREAD_COND_INITIALIZER,nf=PTHREAD_COND_INITIALIZER;
static void *producer(void *arg) {
    (void)arg;
    for (int x=1; x<=ITEMS; ++x) {
        assert((pthread_mutex_lock(&m)) == 0); /* entry section */
        while (count==CAP) assert((pthread_cond_wait(&nf,&m)) == 0);
        buf[tail]=x; tail=(tail+1)%CAP; ++count; /* critical section */
        assert((pthread_cond_signal(&ne)) == 0); assert((pthread_mutex_unlock(&m)) == 0);
    }
    assert((pthread_mutex_lock(&m)) == 0); closed=1;
    assert((pthread_cond_broadcast(&ne)) == 0); assert((pthread_mutex_unlock(&m)) == 0);
    return NULL;
}
static void *consumer(void *arg) {
    (void)arg; int want=1;
    for (;;) {
        assert((pthread_mutex_lock(&m)) == 0);
        while (count==0 && !closed) assert((pthread_cond_wait(&ne,&m)) == 0);
        if (count==0 && closed) { assert((pthread_mutex_unlock(&m)) == 0); break; }
        int x=buf[head]; head=(head+1)%CAP; --count;
        assert(x==want++); sum+=x;
        assert((pthread_cond_signal(&nf)) == 0); assert((pthread_mutex_unlock(&m)) == 0); /* exit */
    }
    assert(want==ITEMS+1); return NULL;
}
int main(void) {
    pthread_t p,c;
    assert((pthread_create(&p,NULL,producer,NULL)) == 0); assert((pthread_create(&c,NULL,consumer,NULL)) == 0);
    assert((pthread_join(p,NULL)) == 0); assert((pthread_join(c,NULL)) == 0);
    assert(count==0 && sum==ITEMS*(ITEMS+1)/2);
    printf("items=%d sum=%d\n",ITEMS,sum);
    assert((pthread_cond_destroy(&ne)) == 0); assert((pthread_cond_destroy(&nf)) == 0);
    assert((pthread_mutex_destroy(&m)) == 0); return 0;
}
```

Why it is correct: Wait atomically releases m and reacquires it. While loops handle spurious wakeups and closure; an empty closed queue ends consumption, while pending items still drain.

