Plan: Save a generation for each barrier wait and keep each round’s data in disjoint storage.

```c
#include <pthread.h>
#include <assert.h>
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static int arrived,generation,slots[3][4],ids[4];
static void meet(void) {
    assert((pthread_mutex_lock(&m)) == 0); int mine=generation;
    if(++arrived==4) { arrived=0; ++generation; assert((pthread_cond_broadcast(&cv)) == 0); }
    else while(generation==mine) assert((pthread_cond_wait(&cv,&m)) == 0);
    assert((pthread_mutex_unlock(&m)) == 0);
}
static void *worker(void *p) {
    int id=*(int *)p;
    for(int r=0;r<3;r++) {
        slots[r][id]=r+id; meet();
        int sum=0; for(int j=0;j<4;j++) sum+=slots[r][j];
        assert(sum==4*r+6);
    } return NULL;
}
int main(void) {
    pthread_t t[4];
    for(int i=0;i<4;i++) { ids[i]=i; assert((pthread_create(&t[i],NULL,worker,&ids[i])) == 0); }
    for(int i=0;i<4;i++) assert((pthread_join(t[i],NULL)) == 0);
    assert(generation==3); assert((pthread_cond_destroy(&cv)) == 0); assert((pthread_mutex_destroy(&m)) == 0); return 0;
}
```

Why it is correct: Each slot has one writer. Barrier mutex handoffs order writes before post-barrier reads. The last arrival advances the generation, and while loops prevent old-round confusion. Later rounds write different slots, so they cannot race with prior-round reads.

