-    (void)p; ck(pthread_mutex_lock(&returns)); ++stock;
-    ck(pthread_mutex_unlock(&returns)); return NULL;
+    (void)p; ck(pthread_mutex_lock(&sales)); ++stock;
+    ck(pthread_mutex_unlock(&sales)); return NULL;
